const enums={status:{planned:'计划',planted:'已埋设',developing:'推进中',recovered:'已回收',abandoned:'已放弃'},category:{other:'其他',family:'亲属',partner:'伙伴',enemy:'敌对',mentor:'师生',affiliation:'归属'},style:{solid:'实线',dashed:'虚线',dotted:'点线'},narrativeKind:{linear:'顺叙',flashback:'倒叙',insert:'插叙',background:'背景事件'}};
const labelsByKey={title:'名称',name:'名称',label:'字段名',type:'类型',kind:'类别',archived:'归档',aliases:'别名',values:'资料字段',storyTime:'故事时间',storyDate:'明确日期',order:'故事排序',narrationOrder:'待写叙述排序',chapterOrders:'章节内排序',narrativeKind:'叙述类型',planned:'计划情境',plannedChapter:'计划卷章',deleted:'已移除',content:'说明原文',status:'状态',targetChapterId:'计划回收章',abandonReason:'放弃原因',enteringRefs:'进入故事资料',memoryRefs:'关联资料',planningRefs:'关联规划',foreshadowRefs:'关联伏笔',chapterRefs:'章节呈现',evidence:'正文依据',eventId:'生效事件',edgeId:'基础关系',value:'关系状态',category:'关系类别',style:'连线样式',active:'关系存在'};
export function historyText(record,{labels={},nodes=[],chapters=[]}={}){
 if(!record)return '记录不存在';
 const ref=(id,list)=>{const n=list.find(n=>n.id===id);return n?`${n.name||n.title}${list.filter(v=>(v.name||v.title)===(n.name||n.title)).length>1?'（'+(list.some(v=>v.id!==id&&(v.name||v.title)===(n.name||n.title)&&v.id.slice(0,8)===id.slice(0,8))?id:id.slice(0,8))+'）':''}`:id;},value=(v,key)=>{
  if(v===null||v===undefined)return '';if(typeof v!=='object')return typeof v==='boolean'?(v?'是':'否'):(enums[key]?.[v]||String(v));
  if(Array.isArray(v))return v.map(item=>typeof item==='string'?(key==='aliases'?item:ref(item,nodes)):typeof item==='object'?Object.keys(item).sort().filter(k=>!['review','excluded','title'].includes(k)).map(k=>`${k==='chapterId'?'章节':k==='revision'?'版本':k==='kind'?'类型':k==='evidence'?'依据原文':k}：${k==='chapterId'?ref(item[k],chapters):value(item[k],k)}`).join('\n'):String(item)).join('\n');
  return Object.keys(v).sort().map(k=>`${key==='values'?(labels[k]||k):key==='chapterOrders'?ref(k,chapters):(labelsByKey[k]||k)}：${value(v[k],k)}`).join('\n');
 };
 return Object.keys(labelsByKey).filter(k=>Object.hasOwn(record,k)&&record[k]!==null&&record[k]!==undefined&&record[k]!==''&&!(Array.isArray(record[k])&&!record[k].length)&&!(typeof record[k]==='object'&&!Object.keys(record[k]).length)&&!(['planned','deleted','archived'].includes(k)&&record[k]===false)).map(k=>`${labelsByKey[k]}：\n${['targetChapterId'].includes(k)?ref(record[k],chapters):value(record[k],k)}`).join('\n\n');
}
